/* Blends from b to c by the eased fraction of x between lo and hi; flag selects the call path. */
float BlendEased(int flag, int n, float x, float b, float c, float lo, float hi)
{
    float t;
    float u;
    float r = 0.0f;
    int i;
    if (x > lo) {
        t = (x - lo) / (hi - lo);
        if (t < 0.0f) {
            t = 0.0f;
        }
        if (t > 1.0f) {
            t = 1.0f;
        }
        for (i = 1; i < n; i++) {
            t = t * t;
        }
        u = 1.0f - t;
        if (flag != 0) {
            r = FastAddRots(b, FastSubRots(c, b) * t);
        } else {
            r = b * u + c * t;
        }
    } else {
        r = b;
    }
    return r;
}
